def solve(nums):
    if not nums:
        return 0

    current_sum = 0
    max_length = 0

    for num in nums:
        current_sum += num
        if current_sum == 0:
            max_length = max(max_length, len(nums))
        else:
            max_length = max(max_length, len(nums) - 1)

    return max_length

